
from builtins import str
from builtins import range
from builtins import object
import time
from taf.ul.trs_e2e_fw.lib.remote_connection.controller import Controller
from taf.ul.trs_e2e_fw.lib.utils.build_download.build_download import BuildDownload
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.resource_file import get_resource_file
logger = BackgroundLogger.Instance()


class Cloud(object):
    def __init__(self):
        self.remote_conn = Controller()

    def cloud_bringup(self, **kwargs):
        self.config_device = get_config_variable([kwargs.get("config_device", "cbts"), "ncir"])
        self.stack_name = get_config_variable([kwargs.get("config_device", "cbts"), "ncir",
                                               "stack_name"])
        self.folder_name = get_config_variable([kwargs.get("config_device", "cbts"), "ncir",
                                                "folder_name"])
        self.controller_instance = get_config_variable([kwargs.get("config_device", "cbts"),
                                                        "controller",
                                                        "instance"])
        self.env_file = get_config_variable([kwargs.get("config_device", "cbts"), "ncir",
                                             "env_file"])
        self.yaml_file = get_config_variable([kwargs.get("config_device", "cbts"), "ncir",
                                              "yaml_file"])
        self.alias = kwargs.get("alias", 'default')
        self.wft_profile = kwargs.get("wft_profile", None)
        self.addons_wft_profile = kwargs.get("addons_wft_profile", None)
        package = kwargs.get("package", 'auto')
        self._login_to_source_openrc()
        logger.debug("download and create image")
        image_name = self._download_and_create_image(package)
        logger.debug("About to edit the image and uvm_image names on the heat file")
        self.edit_heat_file_image_names(image_name=image_name, path_to_filename=self.env_file)
        logger.debug("create stack")
        self._create_stacks_and_update_uids()

    def connect_to_hop(self, **kwargs):
        config_device = kwargs["remote_device"]
        hop_list = kwargs["hop_list"]
        alias = kwargs.get("alias", "default")
        password = None
        command = self._create_command_for_hop_request(config_device, hop_list)
        logger.debug("******* hop request command {}".format(command))
        if isinstance(hop_list, str) or isinstance(hop_list, str):
            if 'controller' in hop_list:
                password = get_config_variable([config_device[0], hop_list.lower(), "password"])
            logger.debug("connecting to hop {}".format(hop_list))
            self.remote_conn.connect_to_hop(command=command[0], alias=alias, password=password)
            logger.debug("successfully connected to hop {}".format(hop_list))
        elif isinstance(hop_list, list):
            for index, item in enumerate(hop_list):
                logger.debug("connecting to hop {}".format(item))
                self.remote_conn.connect_to_hop(command=command[index], alias=alias, password=password)
                logger.debug("successfully connected to hop {}".format(item))

    def exit_from_hop(self, **kwargs):
        alias = kwargs.get("alias", "default")
        hop_list = kwargs.pop("hop_list")
        if isinstance(hop_list, str) or isinstance(hop_list, str):
            self.remote_conn.exit_from_hop_connection(alias)
            logger.debug("successfully exited from hopped {} connection".format(hop_list))
        elif isinstance(hop_list, list):
            for index, item in enumerate(hop_list):
                logger.debug("Exiting from hop {}".format(item))
                self.remote_conn.exit_from_hop_connection(alias)
                logger.debug("successfully exited from hopped {} connection".format(item))

    def _login_to_source_openrc(self):
        output = self.remote_conn.execute_command_on_shell("source openrc.{}".format(self.config_device["user"]),
                                                           self.alias, timeout=5)
        logger.debug("Switching to -- {}".format(output))
        output = self.remote_conn.execute_command_on_shell("cd {}".format(self.folder_name), self.alias)
        logger.debug("Going to folder {}".format(output))

    def _download_and_create_image(self, package):
        if package.lower() == 'auto':
            package = self._download_from_wft(self.wft_profile)
            logger.debug("^^^^^^^^^^^^^ package name is {}".format(package))
            image_name = package[1].replace("{latest_build_num}", package[0]).replace(".qcow2", "")
        else:
            image_name = package
        logger.debug("package name from _download_and_create_image is {}".format(image_name))
        if self._check_if_image_is_active(image_name):
            logger.debug("Image is already present. Check duplicate image")
            self._check_for_duplicate_image(image_name)
            logger.debug("No duplicate image found")
        else:
            self._create_image(image_name)
            logger.debug("******** getting image status ******** {}".format(image_name))
            image_status = self._check_if_image_is_active(image_name)
            logger.debug("******** image creation status ******** {}".format(image_status))
        return image_name

    def edit_heat_file_image_names(self, image_name, path_to_filename):
        logger.debug("Editing the image name on the heat file")
        cmd = r'sed -ri "s/^(\s*)({0}\s*:\s*.+\s*$)/\\1{1}: {2}/" {3}'
        cmd_to_replace_image_name = cmd.format("image", "image", image_name, path_to_filename)
        self.remote_conn.execute_command_on_shell(cmd_to_replace_image_name, self.alias, timeout=5)
        logger.debug("Successfully edited the image name on the heat file")
        # Replace uvm_image: image_name with given image_name
        logger.debug("Editing the uvm_image name on the heat file")
        cmd_to_replace_uvm_image_name = cmd.format("uvm_image", "uvm_image", image_name,
                                                   path_to_filename)
        self.remote_conn.execute_command_on_shell(cmd_to_replace_uvm_image_name, self.alias, timeout=5)
        logger.debug("Successfully edited the uvm_image name on the heat file")

    def _create_stacks_and_update_uids(self):
        if self._check_if_stack_is_present():
            self._remove_stacks()
        self._create_stack()
        logger.debug("create stacks done")
        self._check_if_stack_is_present("CREATE_COMPLETE")

    def _download_from_wft(self, wft_profile):
        build = BuildDownload()
        filters_file = get_resource_file('wft_filters.json')
        logger.info(filters_file)
        download_url, latest_buildnum, package_template = build.find_latest_build(wft_profile)
        logger.info(
            'latest_buildnum: {}, download_url: {}, package_template {}'.format(latest_buildnum,
                                                                                download_url,
                                                                                package_template))
        download_url = download_url.format(latest_build_num=latest_buildnum)
        package_name = package_template.format(latest_build_num=latest_buildnum)
        logger.debug("download url is {}".format(download_url))
        logger.debug("package name is {}".format(package_name))
        wget_cmd = 'wget -O {} {}{}'.format(package_name, download_url, package_name)
        logger.debug(wget_cmd)
        self.remote_conn.execute_command_on_shell(wget_cmd, self.alias)
        return latest_buildnum, package_template
        # return downloaded_file, latest_buildnum, package_template

    def _check_if_image_is_active(self, image_name):
        """Verification of active image in NCIR"""
        logger.debug("checking if image is present")
        cmd = "source openrc.{}; openstack image list | grep {}".format(self.config_device["user"], image_name)
        # output = self.remote_conn.execute_remote_command(cmd, self.alias)
        output = self.remote_conn.execute_command_on_host(command=cmd, return_rc=False, alias=self.alias, pty=False)
        logger.debug("********* output ******* {}".format(output))
        if "active" in str(output):
            return True
        return False

    def _check_for_duplicate_image(self, image_name):
        cmd = "source openrc.{}; openstack image list | grep {}".format(self.config_device["user"], image_name,
                                                                        image_name)
        # output = self.remote_conn.execute_remote_command(cmd, self.alias)
        output = self.remote_conn.execute_command_on_host(command=cmd, return_rc=False, alias=self.alias, pty=False)
        if len(output) > 1:
            raise Exception("More than one image present with name {}".format(image_name))
        time.sleep(5)

    def _check_if_stack_is_present(self, expected_status=None):
        logger.debug("checking if stack is present")
        cmd = "source openrc.{}; openstack stack list | grep {}".format(
            self.config_device["user"], self.stack_name)
        # output = self.remote_conn.execute_remote_command(cmd, self.alias)
        output = self.remote_conn.execute_command_on_host(command=cmd, return_rc=False, alias=self.alias, pty=False)
        logger.debug("********* output ******* {}".format(output))
        if output is not []:
            stack_list = output if self.stack_name in str(output) else None
        elif output is []:
            stack_list = None
        logger.debug("stack list is {} ".format(stack_list))
        if stack_list is None:
            logger.debug("Stack is not present")
            return False
        logger.debug("Stack is present")
        if expected_status is not None and stack_list is not None:
            for item in str(stack_list).split("|"):
                if expected_status == item.strip():
                    logger.debug("Stack status matched with expected status")
        return True

    def _create_image(self, image_name):
        logger.debug("Creating the image")
        cmd = "openstack image create --public --container-format bare --disk-format qcow2 --file {}.qcow2 {}".format(
            image_name, image_name)
        output = self.remote_conn.execute_command_on_shell(cmd, self.alias)
        logger.debug("********* output ******* {}".format(output))
        self._wait_for_image_status(image_name=image_name, expected_status="active")

    def _remove_stacks(self):
        logger.debug("Removing the stack")
        cmd = "source openrc.{}; openstack stack delete {}; y".format(self.config_device["user"],
                                                                      self.stack_name)
        out_val = self.remote_conn.execute_command_on_shell(cmd, self.alias)
        if "Stack not found:" in str(out_val):
            logger.debug("Stack {} is not found".format(self.stack_name))
            return None
        time.sleep(120)
        if self._check_if_stack_is_present():
            logger.debug("failed to delete stack")
        logger.debug("stack deleted successfully")

    def _create_stack(self):
        logger.debug("Creating the stack")
        self.remote_conn.execute_command_on_shell("cd {}".format(self.folder_name), self.alias, timeout=5)
        time.sleep(2)
        cmd = "openstack stack create -f yaml -t {} -e {} {}".format(
            self.yaml_file, self.env_file, self.stack_name)
        output = self.remote_conn.execute_command_on_shell(cmd, self.alias)
        if "Failed to discover available identity" in output:
            raise Exception("Error while creating stack {}".format(output))
        logger.debug("********* output ******* {}".format(output))
        time.sleep(10)
        self._wait_for_stack_status("CREATE_COMPLETE")

    def _wait_for_stack_status(self, expected_status, time_out=120):
        logger.debug("Wait for the stack status {}".format(expected_status))
        cmd = "source openrc.{}; openstack stack list | grep {}".format(self.config_device["user"], self.stack_name)
        for i in range(time_out):
            # output = self.remote_conn.execute_remote_command(cmd, self.alias)
            output = self.remote_conn.execute_command_on_host(command=cmd, return_rc=False, alias=self.alias, pty=False)
            if expected_status.strip() in str(output):
                logger.debug("Expected stack status was found {}".format(expected_status))
                return True
            time.sleep(1)
        logger.debug("Expected stack status was not found {}".format(expected_status))
        return False

    def _wait_for_image_status(self, image_name, expected_status, time_out=120):
        logger.debug("Wait for the image status {}".format(expected_status))
        cmd = "source openrc.{}; openstack image list | grep {}".format(self.config_device[
                                                                            "user"], image_name)
        for i in range(time_out):
            # output = self.remote_conn.execute_remote_command(cmd, self.alias)
            output = self.remote_conn.execute_command_on_host(command=cmd, return_rc=False, alias=self.alias, pty=False)
            if expected_status.strip() in str(output):
                logger.debug("Expected image status was found {}".format(expected_status))
                return True
            time.sleep(1)
        logger.debug("Expected image status was not found {}".format(expected_status))
        return False

    def _create_command_for_hop_request(self, config_device, hop_item):
        command = []
        logger.debug("hop type is {}".format(type(hop_item)))
        logger.debug("hop content is {}".format(hop_item))
        if isinstance(hop_item, str) or isinstance(hop_item, str):
            if hop_item.lower() == 'controller':
                if isinstance(config_device, list):
                    cntrl_instance = get_config_variable([config_device[0], hop_item.lower(),
                                                          "instance"])
                    command.append('controller-{}'.format(cntrl_instance))
                else:
                    raise "config_device is expected to be of list type but passed type is {}".\
                        format(type(config_device))
                return command
            elif hop_item.lower() == 'cpif' or hop_item.lower() == 'upue':
                command.append('ssh {}-0.local'.format(hop_item.lower()))
        elif isinstance(hop_item, list):
            for item in hop_item:
                logger.debug("*** hop item is {}".format(item))
                command.append('ssh {}-0.local'.format(item.lower()))
        else:
            logger.warn("hop_list is expected to be of type list or string but passed type is {}"
                        "".format(type(hop_item)))
        return command
